pub fn dispatch_replace_entries(
    repo: &mut impl crate::kernel::Repository<Ledger>, id: &str, args: ReplaceEntriesArgs, mutations: &mut Vec<crate::kernel::MutationRecord>, owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>, command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
) -> crate::kernel::DispatchResult<Ledger> {

    let with_references = crate::kernel::WithReferences { command_deref: &command_deref, args: &args, owner_deref: &owner_deref };
    let seed_projections = crate::kernel::seeded_projections(&with_references, LEDGER_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        crate::kernel::Hydrate::Act { id: id.to_string() },
        "ReplaceEntries",
        "Corrections::Ledger",
        "Ledger",
        "reference.value",
        &with_references,
        &[

        ],
        None,
        |record| {
        let replaced_entries = args.entries.clone();
        for (i, e) in replaced_entries.iter().enumerate() { if replaced_entries[..i].iter().any(|prior| prior.sequence == e.sequence) { return Err(crate::kernel::Refusal::AlreadyExists(crate::kernel::RefusalSite::AlreadyExistsEntityDuplicate.render(&[("entity", "Entry"), ("aggregate", "Ledger"), ("identity", "sequence.value"), ("offered", &format!("{:?}", e.sequence.value))]))); } }
        record.entries = replaced_entries;
            Ok(())
        },
        &[

        ],
        &ledger_invariants(),
        &["EntriesReplaced"],
        args.to_json(),
        mutations,
        seed_projections,
    )
}

